import {AlertTriangle,ArrowUpRight,CalendarDays,CheckCircle2,ChevronRight,ClipboardList,Clock3,FileClock,RefreshCw,UsersRound} from 'lucide-react';
import {buildDashboardIntelligence} from '../../lib/externalDashboardIntelligence';

const TONES={P1_CRITICAL:'border-red-200 bg-red-50 text-red-800',P2_HIGH:'border-orange-200 bg-orange-50 text-orange-800',P3_MEDIUM:'border-amber-200 bg-amber-50 text-amber-900',P4_LOW:'border-blue-200 bg-blue-50 text-blue-800'};
const KPI=[['Active clients','activeClients',UsersRound,'clients','clients'],['New this month','newClientsThisMonth',ArrowUpRight,'clients','clients'],['Consultations this week','consultationsThisWeek',CalendarDays,'consultations','consultations'],['Follow-ups due today','followupsDueToday',FileClock,'followups','followups'],['Overdue follow-ups','overdueFollowups',Clock3,'followups','followups'],['Overdue tasks','overdueTasks',ClipboardList,'tasks','tasks'],['Onboarding completed','onboardingCompleted',CheckCircle2,'clients','clients'],['Clients needing review','clientsNeedingReview',AlertTriangle,'attention','attention']];

function Distribution({title,data}){const entries=Object.entries(data).filter(([,value])=>value>0);const total=entries.reduce((sum,[,value])=>sum+value,0);return <section className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="font-bold">{title}</h3>{total?<><div className="mt-5 flex h-3 overflow-hidden rounded-full bg-slate-100">{entries.map(([label,value],index)=><span key={label} title={`${label}: ${value}`} style={{width:`${value/total*100}%`}} className={['bg-blue-600','bg-emerald-500','bg-amber-500','bg-slate-400'][index%4]}/>)}</div><div className="mt-4 grid gap-2 text-sm">{entries.map(([label,value])=><div key={label} className="flex justify-between"><span>{label.replaceAll('_',' ')}</span><strong>{value}</strong></div>)}</div></>:<p className="mt-5 text-sm text-slate-500">No confirmed source data yet.</p>}</section>}

export function ExternalIntelligentHome({clients,user,data,state,error,onRetry,onAdd,onNavigate,onOpen}){if(state==='loading')return <div aria-label="Loading dashboard intelligence" className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{Array.from({length:8},(_,i)=><div key={i} className="h-32 animate-pulse rounded-3xl bg-white"/>)}</div>;if(state==='error')return <section role="alert" className="rounded-3xl border border-red-200 bg-red-50 p-6"><h2 className="text-xl font-bold text-red-900">Dashboard intelligence unavailable</h2><p className="mt-2 text-sm text-red-800">{error}. Client records are not presented as empty.</p><button onClick={onRetry} className="mt-5 min-h-11 rounded-xl border border-red-300 px-4 font-bold"><RefreshCw className="mr-2 inline" size={16}/>Retry</button></section>;
  const model=buildDashboardIntelligence({clients,resources:data.resources,notifications:data.notifications});
  return <div className="space-y-6 pb-24 lg:pb-8"><section className="rounded-[28px] bg-gradient-to-br from-slate-950 via-slate-900 to-blue-950 p-6 text-white sm:p-8"><p className="text-sm text-blue-200">{new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}</p><div className="mt-2 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><h2 className="text-3xl font-bold sm:text-4xl">Today, {(user?.name||'Consultant').split(' ')[0]}</h2><p className="mt-2 text-blue-100">Your factual practice priorities, schedule and progress in one place.</p></div><div className="flex gap-2"><button onClick={onAdd} className="min-h-11 rounded-xl bg-white px-4 text-sm font-bold text-slate-950">Add client</button><button onClick={()=>onNavigate('consultations')} className="min-h-11 rounded-xl border border-white/30 px-4 text-sm font-bold">Schedule</button></div></div></section>
    {error&&<p role="status" className="rounded-2xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900">Partial dashboard: {error}. Unavailable metrics are not shown as zero.</p>}<section aria-label="Practice KPIs" className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{KPI.map(([label,key,Icon,target,source])=>{const unavailable=data.unavailable?.includes(source)||(source==='attention'&&data.unavailable?.some(item=>['followups','tasks','goals','notifications'].includes(item)));return <button key={key} onClick={()=>target==='attention'?document.getElementById('needs-attention')?.scrollIntoView({behavior:'smooth'}):onNavigate(target)} className="min-h-32 rounded-3xl border border-slate-200 bg-white p-5 text-left shadow-sm"><span className="grid h-10 w-10 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon size={18}/></span><strong className="mt-4 block text-3xl">{unavailable?'—':model.kpis[key]}</strong><span className="text-sm text-slate-600">{label}{unavailable?' · unavailable':''}</span></button>})}</section>
    <div className="grid gap-6 xl:grid-cols-[1.5fr_.8fr]"><section id="needs-attention" className="rounded-3xl border border-slate-200 bg-white p-5 sm:p-6"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Needs attention</p><h3 className="mt-1 text-xl font-bold">Priority inbox</h3><p className="mt-1 text-sm text-slate-500">Deterministic operational signals—not clinical risk.</p></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{model.items.length} open</span></div><div className="mt-5 space-y-3">{model.items.slice(0,8).map(item=><button key={item.key} onClick={()=>item.target==='client'&&item.client?onOpen(item.client):onNavigate(item.target)} className="flex min-h-20 w-full flex-col gap-3 rounded-2xl border border-slate-200 p-4 text-left sm:flex-row sm:items-center sm:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><strong className="truncate">{item.client?.displayName||'Practice task'}</strong><span className={`rounded-full border px-2 py-1 text-[11px] font-bold ${TONES[item.level]}`}>{item.level==='P1_CRITICAL'?'▲ ':''}{item.label}</span></div><p className="mt-1 text-sm text-slate-700">{item.reason}</p><p className="mt-1 text-xs text-slate-500">{item.age} · {item.signal.replaceAll('_',' ')}</p></div><span className="shrink-0 text-sm font-bold text-blue-700">{item.action}<ChevronRight className="ml-1 inline" size={16}/></span></button>)}{!model.items.length&&<div className="py-12 text-center"><CheckCircle2 className="mx-auto text-emerald-600"/><p className="mt-3 font-bold">No confirmed priorities</p><p className="mt-1 text-sm text-slate-500">The active queue is clear based on loaded source records.</p></div>}</div></section><div className="space-y-6"><Distribution title="Follow-up status" data={model.charts.followups}/><Distribution title="Goal status" data={model.charts.goals}/></div></div>
    <div className="grid gap-6 lg:grid-cols-2"><section className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="font-bold">Upcoming</h3>{model.upcoming.length?<div className="mt-4 space-y-3">{model.upcoming.map(item=><div key={item.id} className="rounded-2xl bg-slate-50 p-4"><strong>{item.title}</strong><p className="mt-1 text-sm text-slate-500">{new Date(item.due_at).toLocaleString()}</p></div>)}</div>:<p className="mt-4 text-sm text-slate-500">No upcoming consultations in the loaded period.</p>}</section><section className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="font-bold">Recent activity</h3>{model.recent.length?<div className="mt-4 space-y-3">{model.recent.map(item=><div key={item.id} className="border-l-2 border-blue-600 pl-3"><strong className="text-sm">{item.title}</strong><p className="text-xs text-slate-500">{new Date(item.created_at).toLocaleString()}</p></div>)}</div>:<p className="mt-4 text-sm text-slate-500">No recent notification activity.</p>}</section></div>
  </div>;
}
